.eon8-live-page .uk-navbar-left img {
    height: 60px;
    width: auto;
    object-fit: contain;
    transition: height 0.35s ease;
    display: block;
    margin-top:-10px;
}
.eon8-live-page .uk-navbar {
    display: flex !important;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    position: relative;
    z-index: 1;
}
.eon8-live-page .uk-navbar-left {
    display: flex !important;
    align-items: center;
    flex-direction: row;
    gap: 80px !important;
    flex-wrap: nowrap;
}
.eon8-live-page .uk-navbar-right {
    display: flex !important;
    align-items: center;
    margin-left: auto;
}
.eon8-live-page .uk-navbar-nav > li > .uk-navbar-dropdown {
    left: 50% !important;
    transform: translateX(-50%) !important;
    right: auto !important;
}
.eon8-live-page .uk-navbar-nav {
    display: flex !important;
    align-items: center;
    flex-direction: row;
    gap: 5px;
    list-style: none;
    margin: 0;
    padding: 0;
}
.eon8-live-page .uk-navbar-nav > li {
    display: flex;
    align-items: center;
    position: relative;
    white-space: nowrap;
}
.eon8-live-page .uk-navbar-nav > li > a {
    display: flex;
    align-items: center;
    padding: 6px 10px;
    font-size: 14px;
    line-height: 1;
    text-decoration: none;
    position: relative;
}
.eon8-live-page .uk-navbar-nav > li > a::after {
    content: "";
    position: absolute;
    bottom: 0;
    left: 10px;
    right: 10px;
    height: 2px;
    transform: scaleX(0);
    transition: transform 0.3s ease;
    transform-origin: left;
}
.eon8-live-page .uk-navbar-nav > li > a:hover::after {
    transform: scaleX(1);
}
@media (max-width: 1024px) {.eon8-live-page .uk-navbar-left img {
