.eon8-live-page .orm-section {
    background:#f8fafc;
    padding: 20px 20px;
    overflow: hidden;
}
.eon8-live-page .orm-container {
    max-width: 1100px;
    margin: auto;
    display: flex;
    align-items: center;
    gap: 60px;
}
.eon8-live-page .orm-content {
    flex: 1;


    opacity: 0;
    transform: translateX(-60px);
    transition: all 0.8s cubic-bezier(0.22, 1, 0.36, 1);
}
.eon8-live-page .orm-content h2 {
    font-size: 34px;
    color: #0f172a;
    margin-bottom: 20px;
    font-weight: 600;
}
.eon8-live-page .intro {
    font-size: 16px;
    color: #475569;
    line-height: 1.7;
    margin-bottom: 15px;
}
.eon8-live-page .desc {
    font-size: 15px;
    color: #64748b;
    margin-bottom: 25px;
}
.eon8-live-page .highlight {
    background: rgba(255,255,255,0.7);
    backdrop-filter: blur(10px);
    padding: 20px;
    border-radius: 12px;
    border: 1px solid rgba(0,0,0,0.05);
    font-size: 15px;
    color: #1e293b;
    box-shadow: 0 10px 30px rgba(0,0,0,0.05);


    opacity: 0;
    transform: translateY(40px) scale(0.98);
    transition: all 0.8s ease;
}
.eon8-live-page .orm-grid {
    flex: 1;
    display: grid;
    grid-template-columns: 1fr;
    gap: 15px;
}
.eon8-live-page .orm-item {
    position: relative;
    padding: 16px 18px 16px 40px;
    background: #ffffff;
    border-radius: 10px;
    font-size: 15px;
    color: #1e293b;
    border: 1px solid #e2e8f0;


    opacity: 0;
    transform: translateY(40px) scale(0.97);
    transition: all 0.6s ease;
}
.eon8-live-page .orm-item:hover {
    transform: translateY(-6px) scale(1.03);
    box-shadow: 0 12px 30px rgba(0,0,0,0.08);
    border-color: #c7d2fe;
}
.eon8-live-page .orm-section.show .orm-content {
    opacity: 1;
    transform: translateX(0);
}
.eon8-live-page .orm-section.show .highlight {
    opacity: 1;
    transform: translateY(0) scale(1);
    transition-delay: 0.2s;
}
.eon8-live-page .orm-section.show .orm-item {
    opacity: 1;
    transform: translateY(0) scale(1);
}
.eon8-live-page .orm-section.show .orm-item:nth-child(1) { transition-delay: 0.1s; }
.eon8-live-page .orm-section.show .orm-item:nth-child(2) { transition-delay: 0.2s; }
.eon8-live-page .orm-section.show .orm-item:nth-child(3) { transition-delay: 0.3s; }
.eon8-live-page .orm-section.show .orm-item:nth-child(4) { transition-delay: 0.4s; }
.eon8-live-page .orm-section.show .orm-item:nth-child(5) { transition-delay: 0.5s; }
.eon8-live-page .orm-section.show .orm-item:nth-child(6) { transition-delay: 0.6s; }
@media (max-width: 900px) {.eon8-live-page .orm-container {
        flex-direction: column;
        gap: 40px;
    }
.eon8-live-page .orm-content {
        transform: translateY(40px);
    }
.eon8-live-page .orm-section.show .orm-content {
        transform: translateY(0);
    }}
.eon8-live-page .roadmap-section.dark-orange {
    background: linear-gradient(135deg, #0a0a0a, #121212, #1a1a1a);
    padding: 10px 20px;
    color: #fff;
    overflow: hidden;
}
.eon8-live-page .roadmap-container {
    max-width: 1050px;
    margin: auto;
}
.eon8-live-page .roadmap-section h2 {
    text-align: center;
    font-size: 36px;
    margin-bottom: 70px;
    color: #ffffff;
}
.eon8-live-page .timeline {
    position: relative;
}
.eon8-live-page .timeline::before {
    content: "";
    position: absolute;
    left: 50%;
    width: 2px;
    height: 100%;
    background: linear-gradient(to bottom, #ff7a18, #ffb347);
    transform: translateX(-50%) scaleY(0);
    transform-origin: top;
    opacity: 0.7;
    transition: transform 1s ease;
}
.eon8-live-page .step {
    width: 50%;
    padding: 25px 45px;
    position: relative;


    opacity: 0;
    transition: all 0.7s ease;
}
.eon8-live-page .step.left {
    left: 0;
    text-align: right;
    transform: translateX(-80px);
}
.eon8-live-page .step.right {
    left: 50%;
    transform: translateX(80px);
}
.eon8-live-page .step::before {
    content: "";
    position: absolute;
    top: 35px;
    width: 14px;
    height: 14px;
    background: #ff7a18;
    border-radius: 50%;
    box-shadow: 0 0 0 6px rgba(255,122,24,0.15);


    transform: scale(0);
    transition: transform 0.4s ease;
}
.eon8-live-page .step.left::before {
    right: -7px;
}
.eon8-live-page .step.right::before {
    left: -7px;
}
.eon8-live-page .content {
    background: linear-gradient(145deg, rgba(255,255,255,0.05), rgba(255,255,255,0.02));
    padding: 22px;
    border-radius: 14px;
    border: 1px solid rgba(255,255,255,0.08);
    backdrop-filter: blur(10px);
    transition: all 0.3s ease;
    position: relative;
}
.eon8-live-page .content::after {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: 14px;
    border: 1px solid rgba(255,122,24,0.15);
    opacity: 0;
    transition: 0.3s;
}
.eon8-live-page .icon {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background: linear-gradient(135deg, #ff7a18, #ffb347);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 13px;
    font-weight: 600;
    color: #111;
    margin-bottom: 12px;
}
.eon8-live-page .content h3 {
    font-size: 18px;
    margin-bottom: 8px;
    color: #fff;
}
.eon8-live-page .content p {
    font-size: 14px;
    color: #cbd5f5;
    line-height: 1.6;
}
.eon8-live-page .content:hover {
    transform: translateY(-6px);
    box-shadow: 0 15px 40px rgba(0,0,0,0.4);
}
.eon8-live-page .content:hover::after {
    opacity: 1;
}
.eon8-live-page .roadmap-section.show .timeline::before {
    transform: translateX(-50%) scaleY(1);
}
.eon8-live-page .roadmap-section.show .step {
    opacity: 1;
    transform: translateX(0);
}
.eon8-live-page .roadmap-section.show .step::before {
    transform: scale(1);
}
.eon8-live-page .roadmap-section.show .step:nth-child(1) { transition-delay: 0.1s; }
.eon8-live-page .roadmap-section.show .step:nth-child(2) { transition-delay: 0.2s; }
.eon8-live-page .roadmap-section.show .step:nth-child(3) { transition-delay: 0.3s; }
.eon8-live-page .roadmap-section.show .step:nth-child(4) { transition-delay: 0.4s; }
.eon8-live-page .roadmap-section.show .step:nth-child(5) { transition-delay: 0.5s; }
@media (max-width: 768px) {.eon8-live-page .timeline::before {
        left: 10px;
    }
.eon8-live-page .step {
        width: 100%;
        padding-left: 45px;
        padding-right: 20px;
        text-align: left;
        transform: translateY(40px);
    }
.eon8-live-page .step.right {
        left: 0;
    }
.eon8-live-page .step::before {
        left: 3px;
    }
.eon8-live-page .roadmap-section.show .step {
        transform: translateY(0);
    }}
.eon8-live-page .visibility-section {

    padding: 10px 20px;
}
.eon8-live-page .visibility-container {
    max-width: 1000px;
    margin: auto;


    padding: 50px;
    border-radius: 16px;
    background: rgba(255,255,255,0.6);
    backdrop-filter: blur(10px);
    box-shadow: 0 20px 50px rgba(0,0,0,0.05);


    opacity: 0;
    transform: translateY(40px);
    transition: all 0.8s cubic-bezier(0.22,1,0.36,1);
}
.eon8-live-page .visibility-header {
    text-align: center;
    margin-bottom: 50px;
}
.eon8-live-page .visibility-header h2 {
    font-size: 32px;
    color: #0f172a;
    margin-bottom: 10px;

    opacity: 0;
    transform: translateY(20px);
    transition: 0.6s ease;
}
.eon8-live-page .visibility-header p {
    color: #475569;
    font-size: 16px;

    opacity: 0;
    transform: translateY(20px);
    transition: 0.6s ease;
}
.eon8-live-page .visibility-content {
    display: flex;
    gap: 60px;
    align-items: flex-start;
}
.eon8-live-page .left-text {
    flex: 1;
    font-size: 16px;
    color: #475569;
    line-height: 1.7;

    opacity: 0;
    transform: translateX(-40px);
    transition: 0.7s ease;
}
.eon8-live-page .right-list {
    flex: 1;
}
.eon8-live-page .line-item {
    padding: 14px 0;
    font-size: 15px;
    color: #1e293b;
    border-bottom: 1px solid #e2e8f0;
    position: relative;
    padding-left: 22px;

    opacity: 0;
    transform: translateX(40px);
    transition: 0.6s ease;
}
.eon8-live-page .line-item::before {
    content: "";
    position: absolute;
    left: 0;
    top: 20px;
    width: 6px;
    height: 6px;
    background: #ff7a18;
    border-radius: 50%;

    transform: scale(0);
    transition: transform 0.3s ease;
}
.eon8-live-page .line-item:last-child {
    border-bottom: none;
}
.eon8-live-page .visibility-section.show .visibility-container {
    opacity: 1;
    transform: translateY(0);
}
.eon8-live-page .visibility-section.show h2 {
    opacity: 1;
    transform: translateY(0);
    transition-delay: 0.1s;
}
.eon8-live-page .visibility-section.show .visibility-header p {
    opacity: 1;
    transform: translateY(0);
    transition-delay: 0.2s;
}
.eon8-live-page .visibility-section.show .left-text {
    opacity: 1;
    transform: translateX(0);
    transition-delay: 0.3s;
}
.eon8-live-page .visibility-section.show .line-item:nth-child(1) {
    opacity: 1; transform: translateX(0); transition-delay: 0.35s;
}
.eon8-live-page .visibility-section.show .line-item:nth-child(2) {
    opacity: 1; transform: translateX(0); transition-delay: 0.4s;
}
.eon8-live-page .visibility-section.show .line-item:nth-child(3) {
    opacity: 1; transform: translateX(0); transition-delay: 0.45s;
}
.eon8-live-page .visibility-section.show .line-item:nth-child(4) {
    opacity: 1; transform: translateX(0); transition-delay: 0.5s;
}
.eon8-live-page .visibility-section.show .line-item:nth-child(5) {
    opacity: 1; transform: translateX(0); transition-delay: 0.55s;
}
.eon8-live-page .visibility-section.show .line-item::before {
    transform: scale(1);
}
@media (max-width: 768px) {.eon8-live-page .visibility-container {
        padding: 25px;
    }
.eon8-live-page .visibility-content {
        flex-direction: column;
        gap: 30px;
    }
.eon8-live-page .left-text {
        transform: translateY(30px);
    }
.eon8-live-page .line-item {
        transform: translateY(30px);
    }
.eon8-live-page .visibility-section.show .left-text, .eon8-live-page .visibility-section.show .line-item {
        transform: translateY(0);
    }}
